kubectl -n ps patch ps ps-cluster1 --type=merge -p '{"spec":{"mysql":{"configuration":"max_connections=333\n"}}}'; T2=$(date +%s); sleep 30; until [ "$(kubectl -n ps get ps ps-cluster1 -o jsonpath={.status.state})" = ready ] && [ "$(kubectl -n ps get sts ps-cluster1-mysql -o jsonpath={.status.updatedReplicas})" = 3 ]; do sleep 5; [ $(( $(date +%s)-T2 )) -gt 900 ] && break; done; echo ROLLED $(( $(date +%s)-T2 ))s; sql $(dbpod) mysql "select @@max_connections"
